    "15": "3...Qd6 4...Nc6 5.d5 Ne5 6.Bf4",
    "16": "3...Qe5+ 4.Be2 Bg4 5.d4",
    "17": "3...Qe6+ 4.Be2 Qg6 5.Nf3 g2 gambit",
    "18": "3...Qe6+ 4.Be2 Nc6 5.d4 Qg6 6.Nb5",
    "19": "Portuguese 3...Bg4 4.Bb5+ Nbd7 5...Bxe2",
    "20": "Portuguese 4.Bb5+ Nbd7 5.Be2 Bf5 6.c4",
    "21": "Portuguese 4...c6 5.dxc6 Nxc6 6.Bxc6+",
    "22": "Portuguese 4...c6 5.dxc6 Bxd1?? mate",
    "23": "Portuguese 4...c6 5.dxc6 bxc6 6.Be2",
    "24": "Portuguese 4...c6 5.dxc6 Qa5+ 6.Nc3",
    "25": "Portuguese 4.Bb5+ Bd7 5.Be2",
    "26": "2...Nf6 3.d4 Qxd5 4.Nc3 transposition",
